describe('User Profile - Timezone Settings', () => {
  beforeEach(() => {
    cy.visit('/user-profile');
  });

  it('should successfully set timezone in profile settings', () => {
    // Verify initial timezone is displayed
    cy.get('[data-testid="current-timezone-display"]').should('be.visible');
    cy.get('[data-testid="current-timezone-display"]').should('contain', 'UTC');

    // Intercept API call to update timezone
    cy.intercept('POST', '/api/user/update-timezone').as('updateTimezone');

    // Find timezone dropdown and select a new timezone
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option"]').click({ force: true });
    cy.get('[data-testid="timezone-option"]').should('contain', 'Europe/Paris');

    // Verify timezone dropdown is still visible
    cy.get('[data-testid="timezone-dropdown"]').should('be.visible');

    // Verify timezone is updated in profile settings
    cy.get('[data-testid="current-timezone-display"]').should('contain', 'Europe/Paris');

    // Verify API call was made
    cy.wait('@updateTimezone').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Timezone updated successfully');
  });

  it('should handle invalid timezone input and display error message', () => {
    // Verify initial timezone is displayed
    cy.get('[data-testid="current-timezone-display"]').should('be.visible');
    cy.get('[data-testid="current-timezone-display"]').should('contain', 'UTC');

    // Intercept API call to update timezone
    cy.intercept('POST', '/api/user/update-timezone').as('updateTimezone');

    // Attempt to set invalid timezone (e.g., non-existent timezone)
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option"]').click({ force: true });
    cy.get('[data-testid="timezone-option"]').type('Invalid/Timezone');

    // Verify invalid timezone is still visible
    cy.get('[data-testid="timezone-dropdown"]').should('be.visible');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid timezone format');

    // Verify API call was not made
    cy.wait('@updateTimezone').then((interception) => {
      expect(interception.request.body.timezone).to.equal('Invalid/Timezone');
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
